'use strict';

// Синтетический корпус ПДн для F-80 (критерий 1 карточки F-80): ФИО в разных падежах, телефоны в 5 форматах,
// почта, СНИЛС, паспорт, полис, ИНН, адрес, дата рождения, ник, ссылка, карта, организация, номер медкарты.
// Все значения вымышлены (номера с нулями, домены example.test), настоящих людей нет (PD-24).
// type — ожидаемый тип ключа #ТИП-N#; values — то, чего не должно быть в запросе к модели.

const CASES = [
  { t: 'Меня зовут Марина Тестова, звоните +7 (912) 000-11-22.', values: [['PERSON', 'Марина Тестова'], ['PHONE', '+7 (912) 000-11-22']] },
  { t: 'Передайте Марине Тестовой, что телефон 8 912 000 11 23.', values: [['PERSON', 'Марине Тестовой'], ['PHONE', '8 912 000 11 23']] },
  { t: 'Номер мужа 89120001124, а мой 912-000-11-25.', values: [['PHONE', '89120001124'], ['PHONE', '912-000-11-25']] },
  { t: 'Резервный номер +79120001126 только для смс.', values: [['PHONE', '+79120001126']] },
  { t: 'Пишите на marina.test@cc.example.test или marina_t13@example.test.', values: [['EMAIL', 'marina.test@cc.example.test'], ['EMAIL', 'marina_t13@example.test']] },
  { t: 'СНИЛС 112-233-445 95, паспорт 4510 000123 выдан в 2015.', values: [['SNILS', '112-233-445 95'], ['PASSPORT', '4510 000123']] },
  { t: 'Полис ОМС 7700000000000013, ИНН 770000000013.', values: [['POLICY', '7700000000000013'], ['INN', '770000000013']] },
  { t: 'Живу г. Тестоград, ул. Синтетическая, д. 5, кв. 12.', values: [['ADDRESS', 'ул. Синтетическая, д. 5, кв. 12']] },
  { t: 'Дата рождения 12.03.1985, медкарта № МК-000123.', values: [['DATE_OF_BIRTH', '12.03.1985'], ['DOC', 'МК-000123']] },
  { t: 'Мой ник в чате @synthetic_marina_t13, профиль https://social.example.test/id000000.', values: [['NICK', '@synthetic_marina_t13'], ['URL', 'https://social.example.test/id000000']] },
  { t: 'Оплатил картой 2200 0000 0000 0013.', values: [['CARD', '2200 0000 0000 0013']] },
  { t: 'Работаю в ООО «Ромашка-Тест», начальник Олег Пробный.', values: [['ORG', 'ООО «Ромашка-Тест»'], ['PERSON', 'Олег Пробный']] },
  { t: 'Вчера говорила с Олегом Пробным и Анной Синтетиковой.', values: [['PERSON', 'Олегом Пробным'], ['PERSON', 'Анной Синтетиковой']] },
  { t: 'Сестра Зоя Вымышленная просила номер +7 912 000-11-27.', values: [['PERSON', 'Зоя Вымышленная'], ['PHONE', '+7 912 000-11-27']] },
  { t: 'Петр Условный (с ё — Пётр Условный) приходил с паспортом 4511 000124.', values: [['PERSON', 'Петр Условный'], ['PERSON', 'Пётр Условный'], ['PASSPORT', '4511 000124']] },
  { t: 'Адрес мамы: г. Тестоград, пр-т Вымышленный, 10-15. Её почта mama@example.test.', values: [['ADDRESS', 'пр-т Вымышленный, 10-15'], ['EMAIL', 'mama@example.test']] },
  { t: 'Игорь Демонстров, родился 01.01.1970, СНИЛС 000-000-000 00.', values: [['PERSON', 'Игорь Демонстров'], ['DATE_OF_BIRTH', '01.01.1970'], ['SNILS', '000-000-000 00']] },
  { t: 'Позвоните Игорю Демонстрову по номеру 8 (912) 000-11-28.', values: [['PERSON', 'Игорю Демонстрову'], ['PHONE', '8 (912) 000-11-28']] },
];

function allValues() {
  return CASES.flatMap((c) => c.values.map(([type, value]) => ({ type, value, text: c.t })));
}

// Типы, которые находят правила кода без NER (F-80 «Сбой распознавания»): не должны утекать никогда.
const RULE_TYPES = new Set(['PHONE', 'EMAIL', 'SNILS', 'PASSPORT', 'POLICY', 'INN', 'CARD', 'DOC', 'URL', 'NICK']);

module.exports = { CASES, allValues, RULE_TYPES };
